(function() {
  
  var body = document.body;
  var htmlEl = document.documentElement;
  var themeBtn = document.getElementById('themeToggle');
  var themeIcon = document.getElementById('themeIcon');
  var SUN = '<path d="M12 4V2M12 22v-2M4 12H2m20 0h-2M5.6 5.6L4.2 4.2m15.6 15.6l-1.4-1.4M5.6 18.4l-1.4 1.4M18.4 5.6l1.4-1.4"/><circle cx="12" cy="12" r="4.5"/>';
  var MOON = '<path d="M21 12.8A9 9 0 1111.2 3 7 7 0 0021 12.8z"/>';

  function applyTheme(theme) {
    htmlEl.setAttribute('data-theme', theme);
    themeIcon.innerHTML = theme === 'light' ? SUN : MOON;
    try { localStorage.setItem('sn-theme', theme); } catch (e) {}
  }
  var savedTheme = 'dark';
  try { savedTheme = localStorage.getItem('sn-theme') || 'dark'; } catch (e) {}
  applyTheme(savedTheme);

  themeBtn.addEventListener('click', function() {
    var next = htmlEl.getAttribute('data-theme') === 'light' ? 'dark' : 'light';
    applyTheme(next);
  });

  
 
 
  var hamburger = document.getElementById('hamburger');
  var backdrop = document.getElementById('sidebarBackdrop');
  var sidebar = document.getElementById('sidebar');

  function closeNav() { body.classList.remove('nav-open'); }
  hamburger.addEventListener('click', function() { body.classList.toggle('nav-open'); });
  backdrop.addEventListener('click', closeNav);
  sidebar.querySelectorAll('a').forEach(function(a) {
    a.addEventListener('click', closeNav);
  });

 
  document.getElementById('year').textContent = new Date().getFullYear();

  
  var RESUME_DATA_URI = "data:application/pdf;base64,";
  document.getElementById('resumeLink').href = RESUME_DATA_URI;
  document.getElementById('resumeLinkMobile').href = RESUME_DATA_URI;
  document.getElementById('resumeLinkIcon').href = RESUME_DATA_URI;

  
  document.getElementById('githubLink').href = 'https://github.com/sivinash';
  
  document.getElementById('projectLink1').href = 'https://github.com/sivinash/turf_booking_using_flask';
  document.getElementById('projectLink2').href = 'https://github.com/sivinash/Alpha-Admin-portal';
  document.getElementById('projectLink3').href = 'https://github.com/sivinash/Alpha-client-portal';

 
  var canvas = document.getElementById('starfield');
  var ctx = canvas.getContext('2d');
  var stars = [];
  var shootingStars = [];
  var rafId = null;

  function resizeCanvas() {
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
  }

  function makeStars() {
    var count = Math.floor((canvas.width * canvas.height) / 9000);
    stars = [];
    for (var i = 0; i < count; i++) {
      stars.push({
        x: Math.random() * canvas.width,
        y: Math.random() * canvas.height,
        r: Math.random() * 1.4 + 0.3,
        baseAlpha: Math.random() * 0.5 + 0.3,
        twinkleSpeed: Math.random() * 0.02 + 0.005,
        phase: Math.random() * Math.PI * 2
      });
    }
  }

  function spawnShootingStar(x, y) {
    var angle = Math.PI * 0.22 + (Math.random() - 0.5) * 0.3;
    shootingStars.push({
      x: x, y: y,
      vx: Math.cos(angle) * 9,
      vy: Math.sin(angle) * 9,
      life: 1
    });
  }

  function draw(t) {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

   
    for (var i = 0; i < stars.length; i++) {
      var s = stars[i];
      var alpha = s.baseAlpha + Math.sin(t * s.twinkleSpeed + s.phase) * 0.3;
      ctx.beginPath();
      ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(230,238,255,' + Math.max(0, Math.min(1, alpha)) + ')';
      ctx.fill();
    }

    
    for (var j = shootingStars.length - 1; j >= 0; j--) {
      var sh = shootingStars[j];
      var tailX = sh.x - sh.vx * 6;
      var tailY = sh.y - sh.vy * 6;
      var grad = ctx.createLinearGradient(sh.x, sh.y, tailX, tailY);
      grad.addColorStop(0, 'rgba(255,255,255,' + sh.life + ')');
      grad.addColorStop(1, 'rgba(120,160,255,0)');
      ctx.strokeStyle = grad;
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(sh.x, sh.y);
      ctx.lineTo(tailX, tailY);
      ctx.stroke();

      sh.x += sh.vx;
      sh.y += sh.vy;
      sh.life -= 0.018;
      if (sh.life <= 0 || sh.x > canvas.width + 50 || sh.y > canvas.height + 50) {
        shootingStars.splice(j, 1);
      }
    }

    rafId = requestAnimationFrame(draw);
  }

  function startStarfield() {
    resizeCanvas();
    makeStars();
    if (!rafId) rafId = requestAnimationFrame(draw);
  }

  startStarfield();

  
  window.addEventListener('click', function(e) {
    if (htmlEl.getAttribute('data-theme') === 'light') return;
    spawnShootingStar(e.clientX, e.clientY);
  });

  window.addEventListener('resize', function() {
    resizeCanvas();
    makeStars();
  });

  
  var starHint = document.getElementById('star-hint');
  if (starHint) {
    setTimeout(function() { starHint.classList.add('show'); }, 900);
    setTimeout(function() { starHint.classList.remove('show'); }, 5500);
  }

  
  var typeTarget = document.getElementById('typeTarget');
  var caret = document.querySelector('.type-caret');
  var reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var segments = [
    { text: "Hi, I'm Sivinash — a ", cls: '' },
    { text: 'Full Stack Developer', cls: 'accent-word' },
    { text: ' from Chennai.', cls: '' }
  ];

  if (typeTarget) {
    if (reduceMotion) {
      segments.forEach(function(seg) {
        var span = document.createElement('span');
        if (seg.cls) span.className = seg.cls;
        span.textContent = seg.text;
        typeTarget.appendChild(span);
      });
      if (caret) caret.classList.add('done');
    } else {
      var segIndex = 0, charIndex = 0;
      var currentSpan = null;

      function typeStep() {
        if (segIndex >= segments.length) {
          if (caret) caret.classList.add('done');
          return;
        }
        var seg = segments[segIndex];
        if (!currentSpan) {
          currentSpan = document.createElement('span');
          if (seg.cls) currentSpan.className = seg.cls;
          typeTarget.appendChild(currentSpan);
        }
        if (charIndex < seg.text.length) {
          currentSpan.textContent += seg.text.charAt(charIndex);
          charIndex++;
          setTimeout(typeStep, 32);
        } else {
          segIndex++;
          charIndex = 0;
          currentSpan = null;
          setTimeout(typeStep, 60);
        }
      }
      setTimeout(typeStep, 300);
    }
  }
})();